// Approach 1: Bill Pugh Initialization-on-Demand Holder (Recommended for Lazy Loading)
public final class DatabasePoolHolder {
    private DatabasePoolHolder() {
        // Guard against reflection instantiation hacks
        if (Holder.INSTANCE != null) {
            throw new IllegalStateException("Singleton instance already created");
        }
    }

    private static class Holder {
        private static final DatabasePoolHolder INSTANCE = new DatabasePoolHolder();
    }

    public static DatabasePoolHolder getInstance() {
        return Holder.INSTANCE;
    }
}

// Approach 2: Double-Checked Locking (DCL) with Volatile Fence
public final class DclConfigurationManager {
    private static volatile DclConfigurationManager instance;
    private final Map<String, String> configs = new ConcurrentHashMap<>();

    private DclConfigurationManager() {}

    public static DclConfigurationManager getInstance() {
        DclConfigurationManager result = instance;
        if (result == null) {
            synchronized (DclConfigurationManager.class) {
                result = instance;
                if (result == null) {
                    instance = result = new DclConfigurationManager();
                }
            }
        }
        return result;
    }
}

// Approach 3: Enum Singleton (100% Immune to Reflection & Deserialization Attacks)
public enum EnterpriseMetricsRegistry {
    INSTANCE;

    private final AtomicLong counter = new AtomicLong();

    public void incrementMetric(String metricName) {
        counter.incrementAndGet();
    }
}
